const date=v=>new Date(v.replace(' ','T')+'Z').toLocaleString('pt-AO',{dateStyle:'short',timeStyle:'medium',timeZone:'Africa/Luanda'});
const icons={wallet:'M3 6h17v14H3V6Z M3 6V4h14 M15 11h6v5h-6z M17 13.5h1',card:'M3 5h18v14H3z M3 9h18 M7 15h4',transfer:'M3 7h17 M16 3l4 4-4 4 M21 17H4 M8 13l-4 4 4 4',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z m-4 9 3 3 5-6',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',bag:'M5 7h14l2 14H3L5 7Z M9 8V6a3 3 0 0 1 6 0v2',box:'m3 7 9-4 9 4-9 4-9-4Z M3 7v10l9 4 9-4V7 M12 11v10 M7 5l10 4',chart:'M4 3v18h17 M8 16v-4 M13 16V8 M18 16V5',cash:'M3 5h18v14H3z M3 9h18 M7 15h3 M16 13v4',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-3-7 M21 3v6h-6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.9 M16 3a4 4 0 0 1 0 8',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',out:'M9 5H4v14h5 M13 12h9 M18 8l4 4-4 4',close:'M6 6l12 12 M18 6 6 18',check:'m5 12 4 4L19 6',leaf:'M20 3C8 2 2 8 5 15s15 5 15-12Z M5 21 16 9',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2V3Z M8 7h8 M8 11h8 M8 15h4',barcode:'M3 4v16 M6 4v16 M10 4v16 M13 4v16 M17 4v16 M21 4v16',trend:'m3 17 6-6 4 4 8-10 M15 5h6v6',print:'M6 8V3h12v5 M6 17H3V8h18v9h-3 M6 13h12v8H6z'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.box}"/></svg>`;
