const manager=()=>state.user.role!=='vendedor';
const can=key=>!!state?.user.permissions?.[key];
const canPage=id=>id==='account'||can(id);
function filterAccessUI(){if(!can('stock_edit')){const form=$('#product-tax-form');if(form){const note=document.createElement('p');note.className='help';note.textContent='Sem permissão para alterar a classificação dos produtos.';form.replaceWith(note);}}for(const b of app.querySelectorAll('[data-page]'))if(!canPage(b.dataset.page))b.remove();for(const b of app.querySelectorAll('[data-action="alerts"]'))if(!can('products'))b.remove();}
const shift=()=>state.current_shift;
function toast(message,error=false){$('#toast').textContent=message;$('#toast').className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').className='',4500);}
async function api(path,body){
 let res;try{res=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});}catch{throw Error('Sem ligação ao servidor. Verifique a ligação e tente novamente.');}
 const raw=await res.text();let result;
 try{result=JSON.parse(raw);}catch{throw Error(`O servidor devolveu uma resposta incompleta (HTTP ${res.status}). Verifique se o servidor continua ativo e se a porta 3000 está aberta; os dados do formulário foram mantidos.`);}
 if(!res.ok){if(res.status===401&&state){state=null;boot();}throw Error(result.error||`Não foi possível concluir o pedido (HTTP ${res.status}).`);}return result;
}
const num=v=>typeof v==='number'?v:Number(String(v||'0').replace(/[\s\u00a0\u202f]/g,'').replace(',','.'));
function numericDisplay(value,decimals=3){const negative=String(value??'').trim().startsWith('-');const raw=String(value??'').replace(/[\s\u00a0\u202f]/g,'').replace('.',',').replace(/[^0-9,]/g,'');const [whole='',...fractions]=raw.split(',');const integer=whole.replace(/^0+(?=\d)/,'').replace(/\B(?=(\d{3})+(?!\d))/g,' ');return (negative?'-':'')+integer+(fractions.length?', '+fractions.join('').slice(0,decimals):'').replace(', ',',');}
const requiredMarker=()=>'<span class="required-marker" aria-hidden="true">*</span>';
function inputLabel(label,id,required){return `<label for="${id}">${esc(label)}${required?' '+requiredMarker():''}</label>`;}
function field(label,name,type='text',value='',extra='',hint=''){
 if(type==='text'&&['category','pack_type','customer','reason','company_address'].includes(name)||(type==='text'&&name==='name'&&!/data-(?:person|product)-name/.test(extra)))extra+=' data-descriptive';
 const password=type==='password',numeric=type==='number';if(type==='tel')extra+=' data-phone';if(type==='email')extra+=' pattern="[a-z0-9_]+@gmail\\.com" placeholder="nome@gmail.com"';if(type==='text'&&name==='barcode')extra+=' maxlength="80"';
 if(numeric){const decimals=extra.includes('step="0.01"')?2:extra.includes('step="0.001"')?3:0;extra=extra.replace(/\bmin=/g,'data-min=').replace(/\bmax=/g,'data-max=').replace(/step="[^"]*"/g,'');extra+=` data-number data-decimals="${decimals}" inputmode="decimal"`;type='text';value=numericDisplay(value,decimals);}
 if(password && name==='password' && !extra.includes('current-password'))extra+=' data-strong-password';
 return `<div class="field">${inputLabel(label,name,/\brequired\b/.test(extra))}<div class="${password?'password-wrap':'input-wrap'}"><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>${password?`<button class="eye-button" type="button" data-eye="${name}" aria-label="Mostrar palavra-passe" aria-pressed="false">${icon('eye')}</button>`:''}</div>${hint?`<small class="field-hint">${esc(hint)}</small>`:''}</div>`;
}
function select(label,name,options,value='',required=true){return `<div class="field">${inputLabel(label,name,required)}<select id="${name}" name="${name}" ${required?'required':''}>${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;}
function formData(form){const d=Object.fromEntries(new FormData(form));for(const input of form.querySelectorAll('[data-number]'))if(input.name)d[input.name]=String(num(input.value));return d;}
function showModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="ghost" data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${body}</div>`;modal.showModal();}
function formError(form,e){let el=form.querySelector('.form-error');if(!el){el=document.createElement('div');el.className='form-error';form.prepend(el);}el.textContent=e.message;}
async function refresh(){state=await api('state');render();}
async function boot(){try{const setup=await api('setup');if(setup.required)return auth(true);try{state=await api('state');render();}catch{auth(false);}}catch(e){app.innerHTML=`<div class="loading"><h1>Não foi possível ligar à TT LEBILA</h1><p>${esc(e.message)}</p><button data-action="retry">Tentar novamente</button></div>`;}}
function registrationFields(){return `<div class="registration-fields">${field('Nome completo','name','text','','required autocomplete="name" data-person-name maxlength="150"')}${field('Bilhete de identidade','bi','text','','required data-bi pattern="[0-9]{9}[A-Za-z]{2}[0-9]{3}" placeholder="009763932CA042" maxlength="14"','9 algarismos + 2 letras + 3 algarismos.')}${field('Data de nascimento','birth_date','date','','required min="1900-01-01" max="'+new Date().toISOString().slice(0,10)+'"')}${field('Telefone','phone','tel','','autocomplete="tel" data-phone maxlength="20" placeholder="+244 923 456 789"')}${field('Email','email','email','','required autocomplete="email" maxlength="254"')}</div>`;}
function credentials(result){showModal('Conta criada · guarde a palavra-passe',`<p>A palavra-passe foi gerada pelo sistema e só será mostrada agora. Entregue-a em privado ao titular da conta.</p><div class="credential"><label>Email</label><div>${esc(result.email)}</div><label>Palavra-passe inicial</label><div class="generated-secret"><code id="generated-password" data-secret="${esc(result.password)}">${esc(result.password)}</code><button type="button" class="eye-button" data-secret-toggle aria-label="Ocultar palavra-passe">${icon('eye')}</button><button type="button" class="secondary small" data-copy-password>Copiar palavra-passe</button><span class="copy-status" role="status" aria-live="polite"></span></div></div><p>Pode iniciar sessão com email ou BI e depois alterar a palavra-passe em <strong>A minha conta</strong>.</p><div class="modal-actions"><button data-action="close">Já guardei a palavra-passe</button></div>`);}
function auth(setup){clearInterval(recoveryTimer);app.innerHTML=`<div class="auth"><section class="auth-hero"><div class="brand"><div class="brand-mark"><span class="tt-symbol">TT</span></div><div class="brand-name">LEBILA<small>COMÉRCIO & GESTÃO</small></div></div><div><div class="eyebrow">MENOS COMPLICAÇÃO. MAIS CONTROLO.</div><h1>O próximo nível<br>do seu <em>negócio.</em></h1><p>Uma visão clara. Uma equipa conectada. O poder de transformar cada atendimento numa nova oportunidade.</p></div><div class="auth-features"><span>01 <b>Stock sob controlo</b></span><span>02 <b>Vendas com confiança</b></span><span>03 <b>Decisões com dados</b></span></div><small>TT LEBILA · Cada dia, mais longe.</small></section><section class="auth-form"><form id="auth-form"><div class="eyebrow">${setup?'CONFIGURAÇÃO INICIAL':'ACESSO RESERVADO À EQUIPA'}</div><h1>${setup?'Cadastrar o proprietário':'Entrar na sua loja'}</h1><p>${setup?'Esta configuração só acontece uma vez. Os próximos cadastros serão feitos pelo gerente ou proprietário. Nome, BI e nascimento não poderão ser alterados.':'Use o seu email ou bilhete de identidade e a sua palavra-passe. Para obter uma conta, contacte o gerente ou proprietário.'}</p>${setup?registrationFields():field('Email ou bilhete de identidade','identifier','text','','required autocomplete="username"')+field('Palavra-passe','password','password','','required autocomplete="current-password"')}<button type="submit">${setup?'Criar conta do proprietário':'Iniciar sessão'} ${icon('arrow')}</button>${!setup?'<button class="forgot-button" type="button" data-action="forgot">Esqueci a palavra-passe</button>':''}<div class="auth-foot">TT LEBILA · O seu negócio, em movimento.</div></form></section></div>`;
 $('#auth-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button:not([type="button"])');b.disabled=true;try{const d=formData(f);if(setup){const result=await api('setup',d);auth(false);credentials(result);}else{await api('login',d);await refresh();}}catch(err){formError(f,err);}finally{b.disabled=false;}};
}
const navs=[['dashboard','grid','Visão geral'],['sales','bag','Ponto de venda'],['products','box','Produtos e stock'],['cash','cash','Caixa'],['history','receipt','Histórico de vendas'],['activity','clock','Atividades'],['fiscal','receipt','IVA e regras fiscais'],['users','users','Equipa e permissões'],['account','users','A minha conta']];
function render(){if(!state)return;if(state.recovery_required)return resetScreen();const currentForm=$('#sale-form');if(currentForm)saleDraft=formData(currentForm);if(!canPage(page))page=navs.find(n=>canPage(n[0]))?.[0]||'account';const title=navs.find(n=>n[0]===page)?.[2]||'Visão geral';app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark"><span class="tt-symbol">TT</span></div><div class="brand-name">LEBILA<small>GESTÃO DA SUA LOJA</small></div></div><div class="nav-label">ESPAÇO DE TRABALHO</div><nav class="nav">${navs.filter(n=>canPage(n[0])).map(([id,i,l])=>`<button data-page="${id}" class="${page===id?'active':''}">${icon(i)}${l}</button>`).join('')}</nav><div class="side-bottom"><div class="side-note">${icon('leaf')}<strong>Crescer começa por cuidar.</strong>Cada produto contado é uma decisão mais segura.</div><div class="user"><div class="avatar">${esc(state.user.name.slice(0,2).toUpperCase())}</div><div><strong>${esc(state.user.name)}</strong><small>${roleLabel[state.user.role]}</small></div><button class="ghost" data-action="logout" title="Terminar sessão">${icon('out')}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">A minha loja <span style="margin:0 12px;color:#ccd3c6">/</span> <b>${title}</b></div><div class="top-right"><span class="date">${new Date().toLocaleDateString('pt-AO',{day:'numeric',month:'long',year:'numeric',timeZone:'Africa/Luanda'})}</span><span><i class="status-dot"></i>Loja conectada</span><button class="ghost" data-action="alerts" title="Alertas de stock">${icon('bell')}</button><button class="ghost mobile-brand" data-action="logout" title="Sair">${icon('out')}</button></div></header><main>${({dashboard:dashboard,sales:pos,products:products,cash:cash,history:history,activity:activity,users:users,account:account,fiscal:fiscalPage}[page]||dashboard)()}<footer class="footer"><span>TT LEBILA · Um negócio mais organizado, todos os dias.</span><span>Valores em Kz · Horários de Angola</span></footer></main></div></div>`;filterAccessUI();bindPage();installFilters();}
function heading(eyebrow,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function metric(label,value,foot,i){return `<div class="metric"><div class="metric-icon">${icon(i)}</div><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`;}
function empty(message,i='box'){return `<div class="empty">${icon(i)}${message}</div>`;}
function dashboard(){const m=state.metrics,low=state.products.filter(p=>p.stock<=p.minimum),growth=m.previous_week?Math.round((m.current_week/m.previous_week-1)*100):null;const trend=growth===null?'A recolher dados':growth>0?'Vendas em crescimento':growth<0?'Vendas a desacelerar':'Vendas estáveis';return dashboardHero()+heading('PAINEL DE CONTROLO','Visão geral','Os números de hoje. As oportunidades de amanhã.',`<button class="secondary" data-page="history">${icon('receipt')}Ver vendas</button><button data-page="sales">${icon('plus')}Nova venda</button>`)+`<div class="metrics">${metric('Vendas de hoje',money(m.today),`<span class="good">${m.count} ${m.count===1?'venda realizada':'vendas realizadas'}</span>`,'chart')}${metric('Ticket médio',money(m.count?Math.round(m.today/m.count):0),'Valor médio por venda hoje','bag')}${metric('Produtos em catálogo',qty(state.products.length),'Categorias que crescem consigo','box')}${metric('Atenção ao stock',`${low.length} <small>produtos</small>`,`<span class="${low.length?'warn':'good'}">${low.length?'Abaixo ou no limite mínimo':'Tudo dentro dos níveis definidos'}</span>`,'bell')}</div><div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>O ritmo das suas vendas</h2><p>Total diário de vendas nos últimos 14 dias</p></div><span class="tag ${growth!==null&&growth<0?'amber':''}">${trend}</span></div><div class="chart-summary"><b>${money(m.current_week)}</b><span>${growth===null?'Sem período anterior para comparar':`${growth>0?'+':''}${growth}% face aos 7 dias anteriores`}<br>Últimos 7 dias</span></div><div class="chart-wrap">${chart()}</div><div class="chart-note">${icon('trend')} ${growth===null?'As tendências aparecem quando houver vendas nos dois períodos.':'Comparação de totais cobrados em 7 dias; inclui IVA quando apurado e não representa lucro.'}</div></section><section class="card"><div class="card-head"><div><h2>Hora de repor</h2><p>Uma prateleira cheia faz a diferença.</p></div><span class="tag amber">${low.length} alertas</span></div><div class="stock-list">${low.slice(0,4).map(p=>`<div class="stock-row"><div class="product-tile">${icon('box')}</div><div><strong>${esc(p.name)}</strong><small>Mínimo: ${qty(p.minimum)} ${esc(p.unit)}</small></div><div class="quantity"><strong>${qty(p.stock)} ${esc(p.unit)}</strong><div class="mini-progress"><i style="width:${Math.min(100,p.minimum?p.stock/p.minimum*100:0)}%"></i></div></div></div>`).join('')||empty('Stock tranquilo por aqui.<br>Os alertas de reposição aparecerão nesta área.','check')}</div><div class="card-foot"><button class="link-btn" data-action="alerts">Consultar stock ${icon('arrow')}</button></div></section></div><section class="card"><div class="card-head table-title"><div><h2>Últimas vendas</h2><p>Um registo de cada atendimento.</p></div><button class="link-btn" data-page="history">Ver todas ${icon('arrow')}</button></div>${salesTable(state.sales.slice(0,5))}</section>`;}
function chart(){
 const mobile=window.innerWidth<480,width=mobile?340:620,left=mobile?47:48,right=width-20,bottom=180;
 const days=Array.from({length:14},(_,i)=>{const d=new Date(Date.now()+3600000);d.setUTCDate(d.getUTCDate()-13+i);return d.toISOString().slice(0,10);});
 const values=days.map(d=>state.chart.find(c=>c.day===d)?.total||0),max=Math.max(...values,10000),x=i=>left+i*((right-left)/13),y=v=>bottom-v/max*140;
 const points=values.map((v,i)=>`${x(i)},${y(v)}`).join(' ');
 return `<svg class="chart" viewBox="0 0 ${width} 220" role="img" aria-label="Receita diária em Kz nos últimos 14 dias"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#3898ff" stop-opacity=".23"/><stop offset="100%" stop-color="#3898ff" stop-opacity=".01"/></linearGradient></defs>${[0,.25,.5,.75,1].map(v=>`<line x1="${left}" y1="${y(v*max)}" x2="${right}" y2="${y(v*max)}" stroke="#e5edf8" stroke-dasharray="4 5"/><text x="${left-10}" y="${y(v*max)+3}" text-anchor="end">${new Intl.NumberFormat('pt',{notation:'compact'}).format(max*v/100)}</text>`).join('')}<polygon points="${left},180 ${points} ${right},180" fill="url(#area)"/><polyline points="${points}" fill="none" stroke="#237cf0" stroke-width="2.5" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="#237cf0"><title>${days[i]}: ${money(v)}</title></circle>`).join('')}${days.map((d,i)=>i%(mobile?4:2)===0||i===13?`<text x="${x(i)}" y="207" text-anchor="middle">${d.slice(8)}/${d.slice(5,7)}</text>`:'').join('')}</svg>`;
}
function salesTable(sales){return !sales.length?empty('Ainda não há vendas.<br>Abra o caixa e registe o primeiro atendimento.','receipt'):`<div class="table-wrap"><table><thead><tr><th>RECIBO</th><th>CLIENTE / DATA</th><th>VENDEDOR / CAIXA</th><th>PAGAMENTO</th><th>TOTAL</th><th></th></tr></thead><tbody>${sales.map(s=>`<tr><td><strong>#${String(s.id).padStart(5,'0')}</strong></td><td><strong>${esc(s.customer)}</strong><span class="sub">${date(s.created)}</span></td><td>${esc(s.seller)}<span class="sub">Caixa #${String(s.shift_id).padStart(4,'0')}</span></td><td><span class="tag gray">${methodLabel[s.method]}</span></td><td><strong>${money(s.total)}</strong></td><td><button class="ghost small" data-receipt="${s.id}">${icon('receipt')}Ver</button></td></tr>`).join('')}</tbody></table></div>`;}
function products(){const list=state.products.filter(p=>(!stockOnly||p.stock<=p.minimum)&&(!category||p.category===category)&&`${p.name} ${p.barcode||''}`.toLowerCase().includes(search.toLowerCase()));return heading('CADA PRODUTO NO SEU LUGAR','Produtos e stock','Embalagens na entrada. Unidades, peso ou volume na venda.',can('stock_edit')?`<button data-action="new-product">${icon('plus')}Adicionar produto</button>`:'')+`<div class="toolbar"><div class="search">${icon('search')}<input id="product-search" placeholder="Pesquisar produto ou código de barras…" value="${esc(search)}" aria-label="Pesquisar produtos"></div><select id="category-filter" aria-label="Categoria"><option value="">Todas as categorias</option>${[...new Set(state.products.map(p=>p.category))].map(c=>`<option ${c===category?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="${stockOnly?'':'secondary'}" data-action="toggle-low">${icon('bell')}Stock baixo</button></div><section class="card">${list.length?`<div class="table-wrap"><table><thead><tr><th>PRODUTO</th><th>CATEGORIA</th><th>STOCK DISPONÍVEL</th><th>EMBALAGEM</th>${can('stock_edit')?'<th>CUSTO / EMBALAGEM</th>':''}<th>PREÇO / UNIDADE</th><th>IVA</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><strong>${esc(p.name)}</strong><span class="sub">${esc(p.barcode||'Sem código de barras')}</span></td><td>${esc(p.category)}</td><td><span class="tag ${p.stock<=p.minimum?'amber':''}">${qty(p.stock)} ${esc(p.unit)}</span><span class="sub">Mínimo: ${qty(p.minimum)} ${esc(p.unit)}</span></td><td>${esc(p.pack_type)} · ${qty(p.pack_size)} ${esc(p.unit)}<span class="sub">Equivale a ${qty(p.stock/p.pack_size)} embalagens</span></td>${can('stock_edit')?`<td>${money(p.pack_cost)}</td>`:''}<td><strong>${money(p.price)}</strong> / ${esc(p.unit)}</td><td><span class="tag gray">${taxLabel(state.fiscal.rules.find(r=>r.id===p.tax_rule_id))}</span></td><td>${can('stock_edit')?`<button class="secondary small" data-stock="${p.id}">${icon('plus')}Entrada</button> <button class="ghost small" data-product="${p.id}">Editar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum produto encontrado.<br>Adicione os seus produtos para começar.')}</section>`+(can('stock_edit')?purchases():'');}
function productModal(id){const p=state.products.find(p=>p.id===id)||{name:'',category:'Alimentares',unit:'un',pack_type:'Caixa',pack_size:12,pack_cost:0,price:0,minimum:5};showModal(id?'Editar produto':'Um novo produto na prateleira',`<form id="product-form"><div class="form-grid"><div class="full">${field('Nome do produto','name','text',p.name,'required data-product-name maxlength="150"')}</div>${field('Categoria (pode criar uma nova)','category','text',p.category,'required list="categories"')}<datalist id="categories">${[...new Set(['Alimentares','Higiene','Bebidas',...state.products.map(p=>p.category)])].map(c=>`<option value="${esc(c)}">`).join('')}</datalist>${select('Unidade de venda','unit',[['un','Unidade'],['kg','Quilograma (kg)'],['L','Litro (L)'],['g','Grama (g)'],['mL','Mililitro (mL)']],p.unit)}${field('Código de barras (opcional)','barcode','text',p.barcode||'','maxlength="80"')}${field('Alerta de stock mínimo','minimum','number',p.minimum,'required min="0" step="0.001"')}${field('Tipo de embalagem','pack_type','text',p.pack_type,'required placeholder="Caixa, pacote, saco…"')}${field('Conteúdo por embalagem (na unidade de venda)','pack_size','number',p.pack_size,'required min="0.001" step="0.001"')}${field('Custo de aquisição por embalagem (Kz)','pack_cost','number',p.pack_cost/100,'required min="0" step="0.01"')}${field('Preço de venda por unidade (Kz) - '+(state.fiscal.settings.enabled?(state.fiscal.settings.price_mode==='included'?'IVA incluído':'sem IVA'):'IVA por definir'),'price','number',p.price/100,'required min="0" step="0.01"')}<div class="full">${select('Regra fiscal deste produto','tax_rule_id',[['','Por definir - não equivale a isenção'],...state.fiscal.rules.filter(r=>r.active||r.id===p.tax_rule_id).map(r=>[String(r.id),r.name+' · '+taxLabel(r)])],p.tax_rule_id?String(p.tax_rule_id):'',false)}<p class="help">A categoria Alimentares não define automaticamente o IVA. Escolha a regra confirmada para este produto.</p></div></div><p class="help">Exemplo: um saco com 25 kg → unidade kg, conteúdo 25. Registe a entrada de stock depois de guardar.</p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>Guardar produto</button></div></form>`);if(!can('fiscal'))$('#tax_rule_id').disabled=true;$('#product-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,d=formData(form);for(const k of ['minimum','pack_size','pack_cost','price'])d[k]=Number(d[k]);if(id)d.id=id;await submit(form,()=>api('products',d),'Produto guardado.');};}
function stockModal(id){const p=state.products.find(p=>p.id===id);showModal('Receber mercadoria',`<form id="stock-form"><h2>${esc(p.name)}</h2><p>1 ${esc(p.pack_type)} = ${qty(p.pack_size)} ${esc(p.unit)} · Custo: ${money(p.pack_cost)}</p>${field('Quantidade de embalagens recebidas','packs','number',1,'required min="0.001" step="0.001"')}${field('Referência / fornecedor / motivo','reason','text','','required placeholder="Ex.: Compra ao fornecedor, documento nº…"')}<p class="help">O stock é convertido automaticamente para a unidade de venda. A entrada não é retirada do caixa de vendas.</p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>Confirmar entrada</button></div></form>`);$('#stock-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=formData(f);await submit(f,()=>api('stock',{...d,packs:Number(d.packs),product_id:id}),'Stock atualizado.');};}
function pos(){const open=shift();const list=state.products.filter(p=>(!category||p.category===category)&&`${p.name} ${p.barcode||''}`.toLowerCase().includes(search.toLowerCase()));return heading('UM BOM ATENDIMENTO COMEÇA AQUI','Ponto de venda','Adicione vários produtos ao carrinho e finalize todos num único recibo.',`<span class="tag ${open?'':'amber'}">${open?'Caixa #'+open.id+' aberto':'Caixa fechado'}</span>`)+(!open?`<div class="banner"><span>Abra o seu caixa para poder finalizar vendas.</span><button class="small" data-action="open-shift">Abrir caixa</button></div>`:'')+fiscalBanner()+`<div class="pos-grid"><section><div class="toolbar"><div class="search">${icon('search')}<input id="pos-search" aria-label="Pesquisar ou ler código" placeholder="Produto ou código de barras + Enter" value="${esc(search)}" autocomplete="off"></div><select id="pos-category" aria-label="Categoria no ponto de venda"><option value="">Todas as categorias</option>${[...new Set(state.products.map(p=>p.category))].map(c=>`<option ${c===category?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="secondary" data-action="refresh-sale">${icon('clock')}Atualizar preços/IVA</button><button class="secondary" data-action="barcode" title="Leitor USB ou Bluetooth">${icon('barcode')}Leitor</button></div><div class="product-grid">${list.map(p=>`<button class="product-button" data-add="${p.id}"><div class="product-tile">${icon(p.category==='Higiene'?'leaf':'box')}</div><strong>${esc(p.name)}</strong><span>${qty(p.stock)} ${esc(p.unit)} disponíveis</span><b>${money(p.price)} <small>/ ${esc(p.unit)}</small></b></button>`).join('')}</div>${!list.length?empty('Nenhum produto encontrado.'):''}</section><section class="card"><div class="card-head"><div><h2>Venda atual</h2><p>${cart.length} ${cart.length===1?'produto distinto':'produtos distintos'} no mesmo recibo</p></div><button class="ghost small" data-action="clear-cart" title="Limpar venda">${icon('close')}</button></div><div class="cart-body"><div id="cart-lines">${cart.length?cart.map(i=>{const p=state.products.find(p=>p.id===i.product_id);return `<div class="cart-item"><div><strong>${esc(p.name)}</strong><small>${money(p.price)} / ${esc(p.unit)}<br><b class="cart-line-total" data-line-total="${p.id}">${money(Math.round(p.price*i.quantity))}</b></small></div><div class="quantity-field"><label for="quantity-${p.id}">Qtd. ${requiredMarker()}</label><input id="quantity-${p.id}" required type="text" inputmode="decimal" data-number data-decimals="3" aria-label="Quantidade de ${esc(p.name)}" data-quantity="${p.id}" value="${numericDisplay(i.quantity)}" data-min="${p.unit==='un'?1:0.001}" step="${p.unit==='un'?1:0.001}"></div><button class="ghost small" data-remove="${p.id}" title="Remover ${esc(p.name)}" aria-label="Remover ${esc(p.name)}">×</button></div>`;}).join(''):empty('O próximo atendimento<br>começa com um produto.','bag')}</div><button type="button" class="secondary continue-shopping" data-action="continue-shopping">${icon('plus')}Continuar a adicionar produtos</button><form id="sale-form">${field('Cliente (opcional)','customer','text',saleDraft.customer,'placeholder="Consumidor final"')}<div class="form-grid">${field('Desconto total (Kz)','discount','number',saleDraft.discount,'required min="0" step="0.01"')}${select('Pagamento','method',Object.entries(methodLabel),saleDraft.method)}</div><div class="totals"><span>Subtotal</span><b id="subtotal"></b></div><div class="totals"><span>Base após desconto</span><b id="tax-base"></b></div><div class="totals"><span>IVA</span><b id="tax-total"></b></div><div class="totals final"><span>Total a pagar</span><span id="sale-total"></span></div>${field('Valor recebido do cliente (Kz)','paid','number',saleDraft.paid,'required min="0" step="0.01"')}<div id="payment-feedback" class="payment-feedback" role="status" aria-live="polite"></div><div class="totals"><span>Troco a entregar</span><b id="sale-change"></b></div><button type="submit" class="checkout" ${!open||!cart.length?'disabled':''}>${icon('check')}Finalizar e emitir recibo</button><p class="help">Stock e preços confirmados ao finalizar. Em TPA / transferência, receba o valor exato.</p></form></div></section></div>`;}
function saleCalculation(){
 const items=cart.map(item=>{const p=state.products.find(p=>p.id===item.product_id);return {...p,quantity:item.quantity,total:Math.round((p?.price||0)*item.quantity)};});
 const subtotal=items.reduce((sum,item)=>sum+item.total,0),discount=Math.round(num($('#discount')?.value||0)*100),raw=$('#paid')?.value??'',paid=raw.trim()===''?null:Math.round(num(raw)*100);
 const invalidQuantity=document.querySelector('[data-quantity]:invalid');if(invalidQuantity)return {subtotal,discount,paid,ok:false,error:invalidQuantity.validationMessage};
 const fiscal=state.fiscal,basket=calculateTaxBasket(items,discount,fiscal.settings,fiscal.rules);
 if(!basket.ok)return {subtotal,discount,paid,...basket};
 const payment=settlement(basket.total,0,paid,$('#method')?.value);
 return {...basket,...payment,subtotal,discount,paid,basket};
}
function updateTotals(){
 const result=saleCalculation();$('#subtotal').textContent=money(result.subtotal);
 $('#sale-total').textContent=result.total===undefined?'—':money(result.total);
 $('#sale-change').textContent=result.ok?money(result.change):'—';
 $('#tax-base').textContent=result.fiscal_state==='applied'?money(result.tax_base):result.fiscal_state==='pending'?'Por apurar':'—';
 $('#tax-total').textContent=result.fiscal_state==='applied'?money(result.tax_total):result.fiscal_state==='pending'?'Não apurado':'—';
 for(const line of result.basket?.lines||[]){const el=document.querySelector(`[data-line-total="${line.id}"]`);if(el){el.textContent=money(line.taxed_total);el.title='Total do produto após desconto e cálculo fiscal, quando ativo.';}}
 const feedback=$('#payment-feedback'),empty=result.paid===null;
 feedback.textContent=!cart.length?'Adicione os produtos da compra.':result.ok?(result.change?`Pagamento suficiente. Entregue ${money(result.change)} de troco.`:'Pagamento exato. Sem troco.'):result.error;
 feedback.className='payment-feedback '+(!cart.length||(empty&&result.total!==undefined)?'neutral':result.ok?'success':'error');
 $('#paid').setAttribute('aria-invalid',String(!empty&&!result.ok));
 $('#discount').setAttribute('aria-invalid',String(result.discount>result.subtotal));
 $('#sale-form .checkout').disabled=!shift()||!cart.length||!result.ok;
}
function cash(){
 const s=shift(),summary=state.cash_summary||{sales_count:0,total_sales:0,cash_total:0,tpa_total:0,transfer_total:0},electronic=summary.tpa_total+summary.transfer_total;
 const expected=s?s.opening+summary.cash_total:0,last=state.shifts.find(sh=>sh.user_id===state.user.id&&sh.closed),average=summary.sales_count?Math.round(summary.total_sales/summary.sales_count):0;
 const payments=[{name:'Dinheiro',detail:'Entra no caixa físico',value:summary.cash_total,icon:'cash',color:'cash'},{name:'TPA / Multicaixa',detail:'Pagamento eletrónico',value:summary.tpa_total,icon:'card',color:'tpa'},{name:'Transferência',detail:'Pagamento eletrónico',value:summary.transfer_total,icon:'transfer',color:'transfer'}];
 return heading('CADA MOVIMENTO, UMA CONTA CERTA','Gestão de caixa','Acompanhe o seu turno, os recebimentos e a conferência num só lugar.',s?`<button class="secondary" data-page="sales">${icon('plus')}Nova venda</button>`:'')+`
 <div class="cash-top-grid"><section class="cash-balance ${s?'':'is-closed'}"><div class="cash-balance-top"><span class="cash-section-label">${icon('wallet')} O MEU CAIXA</span><span class="cash-state ${s?'open':'closed'}"><i></i>${s?'Aberto':'Fechado'}</span></div><div class="cash-balance-copy"><p>${s?'Dinheiro esperado no caixa':'Pronto para um novo começo'}</p><h2>${s?money(expected):'O próximo turno<br>começa consigo.'}</h2><span>${s?'Fundo inicial + vendas em dinheiro, já descontados os trocos.':'Abra o caixa, defina o fundo inicial e dê início a mais um dia de vendas.'}</span></div>${s?`<div class="cash-equation"><div><span>Fundo inicial</span><strong>${money(s.opening)}</strong></div><b>+</b><div><span>Vendas em dinheiro</span><strong>${money(summary.cash_total)}</strong></div><div class="cash-equation-icon">${icon('check')}</div></div>`:`<div class="cash-closed-note">${icon('shield')} ${last?'Último caixa fechado em '+date(last.closed):'Cada turno fica registado do início ao fim.'}</div>`}</section>
 <section class="card cash-turn"><div class="cash-turn-head"><div class="cash-turn-icon">${icon(s?'clock':'shield')}</div><div><h2>${s?'O seu turno em curso':'Tudo pronto para começar'}</h2><p>${s?'Caixa #'+String(s.id).padStart(4,'0'):'Um novo turno, contas organizadas.'}</p></div></div><dl><div><dt>Responsável</dt><dd><span class="cash-mini-avatar">${esc(state.user.name.slice(0,2).toUpperCase())}</span>${esc(state.user.name)}</dd></div><div><dt>${s?'Abertura':'Estado'}</dt><dd>${s?date(s.opened):'Sem caixa aberto'}</dd></div><div><dt>${s?'Última venda':'Última contagem'}</dt><dd>${s?(summary.last_sale_at?date(summary.last_sale_at):'Ainda sem vendas'):(last?money(last.closing):'—')}</dd></div></dl><button class="${s?'secondary':''} cash-turn-action" data-action="${s?'close-shift':'open-shift'}">${icon(s?'check':'plus')}${s?'Fechar o meu caixa':'Abrir o meu caixa'}</button><p class="cash-turn-foot">${icon('shield')} ${s?'Confirme o dinheiro contado antes de encerrar.':'Apenas o seu utilizador movimenta este caixa.'}</p></section></div>
 <div class="cash-kpis">${cashKpi('Vendas do turno',money(summary.total_sales),s?'Total recebido, em todos os métodos':'Os valores aparecem ao abrir o caixa','bag','blue')}${cashKpi('Em dinheiro',money(summary.cash_total),'Trocos já descontados','cash','mint')}${cashKpi('Pagamentos eletrónicos',money(electronic),'TPA + transferências · fora do caixa físico','card','violet')}${cashKpi('Atendimentos',qty(summary.sales_count),summary.sales_count?'Ticket médio: '+money(average):'Cada atendimento, um recibo','receipt','amber')}</div>
 <div class="cash-detail-grid"><section class="card cash-methods"><div class="card-head"><div><h2>Como os clientes pagaram</h2><p>Distribuição das vendas do seu turno.</p></div><span class="tag gray">${s?'Turno atual':'Sem turno ativo'}</span></div><div class="cash-payment-list">${payments.map(p=>{const percent=summary.total_sales?p.value/summary.total_sales*100:0;return `<div class="cash-payment ${p.color}"><div class="cash-payment-icon">${icon(p.icon)}</div><div class="cash-payment-body"><div class="cash-payment-title"><strong>${p.name}</strong><b>${money(p.value)}</b></div><div class="cash-payment-track"><i style="width:${percent}%"></i></div><div class="cash-payment-caption"><span>${p.detail}</span><span>${qty(Math.round(percent*10)/10)}%</span></div></div></div>`;}).join('')}</div><div class="cash-methods-note">${icon('bell')} Apenas pagamentos em dinheiro alteram o valor esperado no caixa físico.</div></section>
 <section class="card cash-recent"><div class="card-head"><div><h2>Últimos recebimentos</h2><p>Os últimos cinco atendimentos deste caixa.</p></div>${icon('receipt')}</div><div class="cash-receipts">${state.cash_recent.length?state.cash_recent.map(v=>`<button class="cash-receipt" data-receipt="${v.id}"><span class="cash-receipt-icon">${icon(v.method==='dinheiro'?'cash':'card')}</span><span class="cash-receipt-copy"><strong>Recibo #${String(v.id).padStart(5,'0')}</strong><small>${date(v.created)} · ${methodLabel[v.method]}</small></span><span class="cash-receipt-amount">${money(v.total)}${icon('arrow')}</span></button>`).join(''):empty(s?'O primeiro atendimento vai aparecer aqui.<br>Registe uma venda para acompanhar os recebimentos.':'Abra o seu caixa para acompanhar<br>os recebimentos deste turno.','receipt')}</div><div class="card-foot"><button class="link-btn" data-page="history">Consultar histórico de vendas ${icon('arrow')}</button></div></section></div>
 <section class="card cash-history"><div class="card-head table-title"><div><h2>Histórico de caixas</h2><p>${manager()?'Os turnos da equipa e o resultado de cada conferência.':'Os seus turnos e o resultado de cada conferência.'}</p></div><span class="tag gray">Últimos 50</span></div>${state.shifts.length?`<div class="table-wrap"><table><thead><tr><th>CAIXA / VENDEDOR</th><th>ABERTURA</th><th>FECHO</th><th>FUNDO</th><th>ESPERADO</th><th>CONTADO</th><th>CONFERÊNCIA</th></tr></thead><tbody>${state.shifts.map(sh=>{const difference=sh.closed?sh.closing-sh.expected:0;return `<tr><td><div class="cash-history-person"><span class="cash-history-symbol">${icon('wallet')}</span><span><strong>#${String(sh.id).padStart(4,'0')} · ${esc(sh.seller)}</strong><small>${sh.closed?'Turno encerrado':'Turno em curso'}</small></span></div></td><td>${date(sh.opened)}</td><td>${sh.closed?date(sh.closed):'<span class="tag">Aberto</span>'}</td><td>${money(sh.opening)}</td><td>${sh.closed?money(sh.expected):'—'}</td><td>${sh.closed?money(sh.closing):'—'}</td><td>${sh.closed?`<span class="cash-reconciliation ${difference<0?'short':difference>0?'over':'exact'}">${icon(difference===0?'check':'bell')}${difference===0?'Conferido':difference<0?'Falta '+money(-difference):'Sobra '+money(difference)}</span>`:'<span class="tag gray">Por conferir</span>'}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Cada abertura e fecho de caixa<br>ficará registado aqui.','clock')}</section>`;
}
function cashKpi(label,value,description,i,color){return `<section class="cash-kpi ${color}"><div class="cash-kpi-icon">${icon(i)}</div><div><p>${label}</p><strong>${value}</strong><small>${description}</small></div></section>`;}
function shiftModal(close=false){showModal(close?'Fechar e conferir o caixa':'Começar um novo caixa',`<form id="shift-form"><p>${close?'Conte o dinheiro físico, incluindo o fundo inicial. O sistema irá registar a diferença em relação ao esperado.':'Indique o dinheiro disponível para trocos no início do turno.'}</p>${close?`<div class="cash-modal-summary"><span>${icon('wallet')} Caixa #${String(shift().id).padStart(4,'0')}</span><div><small>Dinheiro esperado</small><strong>${money(shift().opening+shift().cash_sales)}</strong></div><p>Inclui o fundo inicial e as vendas em dinheiro. TPA e transferências ficam de fora.</p></div>`:`<div class="cash-open-guide">${icon('shield')}<span><strong>Comece com o valor certo.</strong><small>O fundo inicial será somado às vendas em dinheiro para conferir o turno.</small></span></div>`}${field(close?'Dinheiro contado (Kz)':'Fundo inicial (Kz)',close?'closing':'opening','number','','required min="0" step="0.01"')}${close?'<div id="cash-feedback" class="payment-feedback neutral" role="status" aria-live="polite">Indique o dinheiro contado. Qualquer diferença ficará registada no fecho.</div>':''}<div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>${close?'Confirmar fecho':'Abrir caixa'}</button></div></form>`);if(close)$('#closing').addEventListener('input',()=>{const current=shift(),expected=current.opening+current.cash_sales;const result=compareAmounts(expected,Math.round(num($('#closing').value)*100));const el=$('#cash-feedback');el.textContent=!result.ok?result.error:result.shortfall?`Valor em caixa insuficiente. Faltam ${money(result.shortfall)} face ao esperado. Pode confirmar para registar esta falta.`:result.excess?`Existem ${money(result.excess)} a mais no caixa. A diferença ficará registada.`:'Valor contado igual ao esperado.';el.className='payment-feedback '+(!result.ok||result.shortfall?'error':result.excess?'neutral':'success');});$('#shift-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=formData(f);const key=close?'closing':'opening';await submit(f,()=>api('shifts/'+(close?'close':'open'),{[key]:Number(d[key])}),close?'Caixa fechado. Consulte a diferença no histórico.':'Caixa aberto. Boas vendas!');};}
let historyResult=null,historyRequest=0,historyTimer;
function history(){return heading('CADA VENDA TEM UMA HISTÓRIA','Histórico de vendas',manager()?'Consulte todas as vendas ou filtre pelas suas vendas, por pessoa e por caixa.':'Aqui encontra apenas as vendas dos seus próprios caixas.',`<button class="secondary" data-action="export" disabled>${icon('receipt')}Exportar página CSV</button>`)+`<section class="card"><form id="history-form" class="filter-bar history-filters"><div class="history-filter-heading">${icon('search')}<div><strong>Encontrar uma venda</strong><small>Escolha o tipo de pesquisa e ajuste os filtros.</small></div></div>${manager()?select('Vendas de','scope',[['all','Histórico geral'],['mine','As minhas vendas']],'all',false):'<p class="help">Acesso limitado às vendas dos seus caixas.</p>'}${field('Pesquisa recibo','q','text','','maxlength="150" placeholder="Número do recibo"')}${select('Pesquisar por','search_by',[['receipt','Recibo'],['customer','Cliente'],['seller','Vendedor']],'receipt',false)}${select('Pagamento','method',[['','Todos'],...Object.entries(methodLabel)],'',false)}${field('De','start','date')}${field('Até','end','date')}${field('Caixa nº','shift_id','text','','inputmode="numeric" pattern="[0-9]*" maxlength="12"')}<div class="history-filter-actions"><button type="submit">Filtrar</button><button type="button" class="ghost" data-action="clear-history">Limpar filtros</button></div></form><div id="history-results" aria-live="polite"><div class="empty">A carregar o histórico…</div></div></section>`;}
function bindHistory(){historyResult=null;clearTimeout(historyTimer);const form=$('#history-form');form.onsubmit=e=>{e.preventDefault();clearTimeout(historyTimer);loadHistory();};form.addEventListener('input',()=>{$('#q').placeholder={receipt:'Número do recibo',customer:'Nome do cliente',seller:'Nome do vendedor'}[$('#search_by').value];clearTimeout(historyTimer);historyTimer=setTimeout(()=>loadHistory(),250);});loadHistory();}
async function loadHistory(pageNumber=1){
 const form=$('#history-form');if(!form)return;const target=$('#history-results'),sequence=++historyRequest,exportButton=app.querySelector('[data-action="export"]');
 exportButton.disabled=true;target.setAttribute('aria-busy','true');
 try{
  const result=await api('sales/history',{...formData(form),page:pageNumber});
  if(!form.isConnected||sequence!==historyRequest)return;
  historyResult=result;
  const scope=$('#scope');if(scope){const value=scope.value;scope.innerHTML='<option value="all">Histórico geral</option><option value="mine">As minhas vendas</option>'+result.sellers.map(u=>`<option value="${u.id}">${esc(u.name)} · #${u.id}${u.deleted_at?' (conta removida)':''}</option>`).join('');scope.value=value;}
  target.innerHTML=`<div class="history-summary"><span><strong>${qty(result.summary.count)}</strong> ${result.summary.count===1?'venda encontrada':'vendas encontradas'}</span><span>Total dos filtros: <strong>${money(result.summary.total)}</strong></span><span>Página ${result.page} de ${result.pages}</span></div>${result.sales.length?salesTable(result.sales):empty('Nenhuma venda corresponde aos filtros.','receipt')}<div class="history-pagination"><button class="secondary small" data-history-page="${result.page-1}" ${result.page<=1?'disabled':''}>Anterior</button><span>Até ${result.page_size} vendas por página · valores do resumo incluem todas as páginas</span><button class="secondary small" data-history-page="${result.page+1}" ${result.page>=result.pages?'disabled':''}>Seguinte</button></div>`;
  exportButton.disabled=!result.sales.length;
 }catch(e){if(form.isConnected&&sequence===historyRequest){historyResult=null;target.innerHTML=`<div class="notice error">${esc(e.message)}</div>`;}}
 finally{if(form.isConnected&&sequence===historyRequest)target.setAttribute('aria-busy','false');}
}
function activity(){return heading('TRANSPARÊNCIA EM CADA PASSO','Histórico de atividades','Últimos 100 registos: quem fez, o que fez e quando.')+`<section class="card">${state.audit.length?`<div class="table-wrap"><table><thead><tr><th>ATIVIDADE</th><th>DETALHES</th><th>RESPONSÁVEL</th><th>DATA E HORA</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td><span class="audit-type"></span><strong>${esc(a.action)}</strong></td><td>${esc(a.detail)}</td><td>${esc(a.actor)}</td><td>${date(a.created)}</td></tr>`).join('')}</tbody></table></div>`:empty('As ações da sua equipa ficarão registadas aqui.','clock')}</section>`;}
function users(){return heading('PESSOAS QUE FAZEM A TT LEBILA','Equipa e permissões','Um proprietário. Um gerente. Uma equipa de vendedores.',`<button data-action="new-user">${icon('plus')}Adicionar pessoa</button>${state.user.role==='proprietario'?'<button class="secondary" data-action="transfer">Transferir propriedade</button>':''}`)+`<div class="team-summary"><span>${icon('users')} ${state.users.length} pessoas na equipa</span><span>Proprietário: ${esc(state.users.find(u=>u.role==='proprietario')?.name||'—')}</span><span>Gerente: ${esc(state.users.find(u=>u.role==='gerente')?.name||'Por definir')}</span></div><section class="card"><div class="table-wrap"><table><thead><tr><th>NOME / BI</th><th>NASCIMENTO</th><th>CONTACTOS</th><th>PERFIL</th><th>ESTADO</th><th>GESTÃO</th></tr></thead><tbody>${state.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong><span class="sub">${esc(u.bi||'Por completar')}</span></td><td>${esc(u.birth_date||'—')}</td><td>${esc(u.email||'—')}<span class="sub">${esc(u.phone||'—')}</span></td><td><span class="tag ${u.role==='proprietario'?'blue':''}">${roleLabel[u.role]}</span></td><td><span class="tag ${u.active?'':'gray'}">${u.active?'Ativo':'Inativo'}</span></td><td>${(state.user.role==='proprietario'||u.role==='vendedor'||u.id===state.user.id)?`<button class="secondary small" data-contact="${u.id}">Contactos</button>`:''} ${u.id!==state.user.id&&u.role!=='proprietario'&&(state.user.role==='proprietario'||u.role==='vendedor')?`<div class="row-actions"><button class="secondary small" data-access="${u.id}">Acesso</button><button class="ghost small" data-reset="${u.id}">Repor senha</button><button class="danger small" data-remove-user="${u.id}">Remover</button></div>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;}
function userModal(){showModal('Cadastrar uma pessoa',`<form id="user-form">${registrationFields()}${select('Perfil de acesso','role',state.user.role==='proprietario'&&!state.users.some(u=>u.role==='gerente')?[['vendedor','Vendedor'],['gerente','Gerente']]:[['vendedor','Vendedor']],'vendedor')}<p class="help">Confira os dados: nome, BI e nascimento não poderão ser alterados. Será gerada uma palavra-passe única.</p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>Criar utilizador</button></div></form>`);$('#user-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button:not([type="button"])');b.disabled=true;try{const r=await api('users',formData(f));modal.close();await refresh();credentials(r);}catch(err){formError(f,err);}finally{b.disabled=false;}};}
function accessModal(id){
 const u=state.users.find(u=>u.id===id);
 showModal('Permissões de '+esc(u.name),`<form id="access-form">${select('Perfil','role',state.user.role==='proprietario'&&(!state.users.some(x=>x.role==='gerente')||u.role==='gerente')?[['vendedor','Vendedor'],['gerente','Gerente']]:[['vendedor','Vendedor']],u.role)}${select('Estado da conta','active',[['true','Ativo'],['false','Inativo']],String(!!u.active))}<fieldset class="access-options"><legend>Áreas e operações permitidas</legend><div id="permission-options"></div></fieldset><p class="help">Vendedores nunca podem alterar produtos ou stock diretamente, gerir a equipa ou consultar atividades internas. A venda reduz o stock automaticamente. Retirar Caixa também impede novas vendas. Retirar a consulta de stock impede alterações diretas de stock. As sessões desta pessoa serão terminadas ao guardar.</p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>Guardar permissões</button></div></form>`);
 const draw=()=>{const role=$('#role').value,current=permissions(role,role===u.role?u.permissions:{});$('#permission-options').innerHTML=Object.entries(permissionLabels).filter(([key])=>(role!=='vendedor'||sellerKeys.includes(key))).map(([key,label])=>`<label class="access-option"><input type="checkbox" name="permission_${key}" data-permission="${key}" ${current[key]?'checked':''} ${state.user.role==='gerente'&&!can(key)?'disabled':''}><span>${esc(label)}${state.user.role==='gerente'&&!can(key)?'<small>Reservado ao proprietário: não possui este acesso.</small>':''}</span></label>`).join('');};
 draw();$('#role').onchange=draw;
 $('#access-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=formData(f),selected=Object.fromEntries([...f.querySelectorAll('[data-permission]:not(:disabled)')].map(el=>[el.dataset.permission,el.checked]));await submit(f,()=>api('users/access',{id,role:d.role,active:d.active==='true',permissions:selected}),'Permissões atualizadas.');};
}
function contactModal(id){const u=state.users.find(u=>u.id===id);showModal('Contactos de '+esc(u.name),`<form id="contact-form">${field('Email','email','email',u.email,'required')}${field('Telefone','phone','tel',u.phone||'','')}<p class="help">O email atualizado passa a ser usado no login. O BI mantém-se válido.</p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>Guardar contactos</button></div></form>`);$('#contact-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;await submit(f,()=>api('users/profile',{id,...formData(f)}),'Contactos atualizados.');};}
function account(){const u=state.user;return heading('OS SEUS DADOS E A SUA SEGURANÇA','A minha conta','Pode alterar os contactos e a palavra-passe. Os dados de identidade são permanentes.')+`<div class="dashboard-grid"><section class="card shift-card"><h2>Identificação</h2><p>Nome: <strong>${esc(u.name)}</strong><br>BI: <strong>${esc(u.bi)}</strong><br>Nascimento: <strong>${esc(u.birth_date)}</strong></p><hr><form id="profile-form">${field('Email','email','email',u.email,'required')}${field('Telefone','phone','tel',u.phone||'','')}<button>Guardar contactos</button></form></section><section class="card shift-card"><h2>Alterar palavra-passe</h2><p>Pelo menos 8 caracteres, com letras, números e um carácter especial.</p><form id="password-form">${field('Palavra-passe atual','current_password','password','','required autocomplete="current-password"')}${field('Nova palavra-passe','password','password','','required minlength="8" autocomplete="new-password"')}${field('Confirmar nova palavra-passe','confirmation','password','','required minlength="8" autocomplete="new-password"')}<button>Alterar palavra-passe</button></form><div class="account-recovery"><h3>Esqueceu a palavra-passe?</h3><p>A palavra-passe atual está protegida e não pode ser consultada. Recupere o acesso para definir uma nova.</p><button type="button" class="secondary" data-action="account-recovery">Recuperar acesso</button></div></section></div>`;}
function purchases(){return `<section class="card" style="margin-top:24px"><div class="card-head table-title"><div><h2>Compras e entradas de stock</h2><p>Últimos 100 registos · data e hora de Angola</p></div></div>${state.purchases.length?`<div class="table-wrap"><table><thead><tr><th>DATA E HORA</th><th>PRODUTO</th><th>QUANTIDADE</th><th>CUSTO</th><th>RESPONSÁVEL</th><th>REFERÊNCIA</th></tr></thead><tbody>${state.purchases.map(m=>`<tr><td>${date(m.created)}</td><td><strong>${esc(m.product)}</strong></td><td>${qty(m.quantity)} ${esc(m.unit)}</td><td>${money(m.cost)}</td><td>${esc(m.actor)}</td><td>${esc(m.reason)}</td></tr>`).join('')}</tbody></table></div>`:empty('As entradas de mercadoria serão registadas com data, hora e responsável.','clock')}</section>`;}
async function showReceipt(id){try{
 const r=await api('sales/'+id),f=r.fiscal_snapshot,applied=r.fiscal_state==='applied';
 showModal('Recibo da venda',`<div class="receipt"><div class="receipt-title"><h2>TT LEBILA</h2>${f?.company_nif?`<div>NIF: ${esc(f.company_nif)}</div><div>${esc(f.company_address)}</div>`:''}<div>COMPROVATIVO INTERNO DE VENDA</div><strong>N.º ${String(r.id).padStart(5,'0')}</strong></div><div>Data: ${date(r.created)}</div><div>Vendedor: ${esc(r.seller)}</div><div>Cliente: ${esc(r.customer)}</div><div>Caixa: #${r.shift_id}</div><p class="receipt-note">${applied?(f.price_mode==='included'?'Preços com IVA incluído.':'Preços sem IVA; imposto acrescido após desconto.'):'IVA não apurado. Configuração pendente ou venda anterior ao módulo fiscal.'}</p><table><thead><tr><th>Produto</th><th>Qtd.</th><th>Preço</th><th>IVA</th><th>Total</th></tr></thead><tbody>${r.items.map(i=>`<tr><td>${esc(i.name)}${i.discount_amount?`<br>Desc.: ${money(i.discount_amount)}`:''}</td><td>${qty(i.quantity)} ${esc(i.unit)}</td><td>${money(i.price)}</td><td>${applied?taxLabel(i.tax_snapshot)+'<br><small>'+money(i.tax_amount)+'</small>':'Por apurar'}</td><td>${money(i.taxed_total??i.total)}</td></tr>`).join('')}</tbody></table><div class="totals"><span>Subtotal dos preços</span><span>${money(r.subtotal)}</span></div><div class="totals"><span>Desconto</span><span>− ${money(r.discount)}</span></div>${applied?`<div class="totals"><span>Base após desconto</span><span>${money(r.tax_base)}</span></div><div class="totals"><span>IVA</span><span>${money(r.tax_total)}</span></div>`:'<div class="totals"><span>IVA</span><span>Não apurado</span></div>'}<div class="totals final"><span>Total pago pela compra</span><span>${money(r.total)}</span></div><div class="totals"><span>Valor entregue</span><span>${money(r.paid)}</span></div><div class="totals"><span>Troco entregue</span><span>${money(r.change_due)}</span></div><div>Pagamento: ${methodLabel[r.method]}</div>${applied?`<h3>Discriminação de IVA</h3><table><thead><tr><th>Regra / taxa</th><th>Base</th><th>IVA</th></tr></thead><tbody>${(f.groups||[]).map(g=>`<tr><td>${esc(g.name)} · ${taxLabel(g)}<br>${esc(g.legal_basis)}</td><td>${money(g.tax_base)}</td><td>${money(g.tax_amount)}</td></tr>`).join('')}</tbody></table><p class="receipt-note">Regime: ${esc(f.regime)}. ${esc(f.legal_basis)}</p>`:''}<div class="disclaimer">Obrigado pela sua preferência!<br>Documento interno sem validade fiscal.<br>Não substitui uma fatura emitida por software certificado.</div></div><div class="modal-actions"><button class="secondary" data-action="close">Fechar</button><button data-action="print">${icon('print')}Imprimir</button></div>`);
 }catch(e){toast(e.message,true);}}
async function submit(form,fn,message){const b=form.querySelector('button:not([type="button"])');if(b)b.disabled=true;try{await fn();modal.close();await refresh();toast(message);}catch(e){formError(form,e);}finally{if(b)b.disabled=false;}}
function bindPage(){if(page==='fiscal')bindFiscal();if(page==='account'){
 $('#profile-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;await submit(f,()=>api('profile',formData(f)),'Contactos atualizados.');};
 $('#password-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=formData(f);if(d.password!==d.confirmation)return formError(f,Error('As palavras-passe não coincidem.'));await submit(f,()=>api('password',d),'Palavra-passe alterada. Outras sessões foram terminadas.');};
 }
if(page==='products'){$('#product-search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#product-search').focus();$('#product-search').setSelectionRange(pos,pos);};$('#category-filter').onchange=e=>{category=e.target.value;render();};}
  if(page==='sales'){$('#pos-category').onchange=e=>{category=e.target.value;render();};$('#pos-search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#pos-search').focus();$('#pos-search').setSelectionRange(pos,pos);};$('#pos-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const p=state.products.find(p=>p.barcode===e.target.value.trim());if(p){addCart(p.id);search='';render();$('#pos-search').focus();}else toast('Código não encontrado. Registe-o no produto.',true);}};updateTotals();for(const id of ['discount','paid'])$('#'+id).oninput=updateTotals;$('#method').onchange=()=>{if($('#method').value!=='dinheiro'){const current=saleCalculation();if(current.basket?.ok)$('#paid').value=numericDisplay(current.basket.total/100,2);}updateTotals();};$('#sale-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=formData(f),b=f.querySelector('button:not([type="button"])');b.disabled=true;try{const check=saleCalculation();if(!check.ok)throw Error(check.error);const receipt=await api('sales',{...d,discount:Number(d.discount),paid:Number(d.paid),items:cart,expected_total:check.total,expected_fiscal_revision:state.fiscal.revision});cart=[];saleDraft={customer:'',discount:'0',paid:'',method:'dinheiro'};f.reset();await refresh();await showReceipt(receipt.id);toast('Venda registada. Stock atualizado.');}catch(err){formError(f,err);}finally{b.disabled=false;}};}
  if(page==='history')bindHistory();
}
function addCart(id){const p=state.products.find(p=>p.id===id),current=cart.find(i=>i.product_id===id),amount=p.unit==='un'?1:Math.min(1,p.stock);if(p.stock<=0||(current?.quantity||0)+amount>p.stock){toast(`Stock insuficiente para ${p.name}. Disponível: ${qty(p.stock)} ${p.unit}; já no carrinho: ${qty(current?.quantity||0)} ${p.unit}.`,true);return false;}if(current)current.quantity=Math.round((current.quantity+amount)*1000)/1000;else cart.push({product_id:id,quantity:amount});return true;}
function updateCartQuantity(el){
 const id=Number(el.dataset.quantity),item=cart.find(i=>i.product_id===id),p=state?.products.find(p=>p.id===id);if(!item||!p)return;
 const value=num(el.value);let message='';
 if(!el.value.trim()||!Number.isFinite(value)||value<=0)message='Indique uma quantidade superior a zero.';
 else if(p.unit==='un'&&!Number.isInteger(value))message='Este produto é vendido em unidades inteiras.';
 else if(value>p.stock)message=`Stock insuficiente para ${p.name}. Faltam ${qty(value-p.stock)} ${p.unit}; disponíveis ${qty(p.stock)} ${p.unit}.`;
 el.setCustomValidity(message);el.setAttribute('aria-invalid',String(!!message));
 if(!message){item.quantity=value;const total=el.closest('.cart-item')?.querySelector('.cart-line-total');if(total)total.textContent=money(Math.round(p.price*value));}
 if(page==='sales')updateTotals();
}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
  if(b.dataset.historyPage){clearTimeout(historyTimer);return loadHistory(Number(b.dataset.historyPage));}
  if(b.hasAttribute('data-copy-password')){
   const code=$('#generated-password');if(!code)return;
   const status=modal.querySelector('.copy-status');
   let copied=false;
   try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(code.dataset.secret);copied=true;}}catch{}
   if(!copied){const temporary=document.createElement('textarea');temporary.value=code.dataset.secret;temporary.setAttribute('aria-label','Palavra-passe para copiar');temporary.style.cssText='position:fixed;opacity:0';modal.append(temporary);temporary.select();try{copied=document.execCommand('copy');}catch{}temporary.remove();b.focus();}
   if(status?.isConnected)status.textContent=copied?'Palavra-passe copiada.':'Não foi possível copiar. Mostre a palavra-passe e selecione-a para copiar manualmente.';
   return;
  }
  if(b.hasAttribute('data-secret-toggle')){const code=$('#generated-password');const hidden=code.textContent.startsWith('•');code.textContent=hidden?code.dataset.secret:'••••••••••••';b.setAttribute('aria-label',hidden?'Ocultar palavra-passe':'Mostrar palavra-passe');return;}
  if(b.dataset.eye){const input=document.getElementById(b.dataset.eye);const showing=input.type==='password';input.type=showing?'text':'password';b.setAttribute('aria-label',showing?'Ocultar palavra-passe':'Mostrar palavra-passe');b.setAttribute('aria-pressed',String(showing));return;}
  if(b.dataset.removeUser)return removeUserModal(Number(b.dataset.removeUser));
  if(b.dataset.page){if(!canPage(b.dataset.page))return toast('Não tem acesso a esta área.',true);page=b.dataset.page;search='';category='';stockOnly=false;filters={};render();window.scrollTo(0,0);return;}
  if(b.dataset.contact)return contactModal(Number(b.dataset.contact));if(b.dataset.reset){const id=Number(b.dataset.reset);showModal('Repor palavra-passe?',`<p>A palavra-passe atual será substituída e as sessões desta pessoa serão terminadas.</p><div class="modal-actions"><button class="secondary" data-action="close">Cancelar</button><button data-confirm-reset="${id}">Gerar nova palavra-passe</button></div>`);return;}if(b.dataset.confirmReset){b.disabled=true;try{const r=await api('users/reset-password',{id:Number(b.dataset.confirmReset)});modal.close();credentials(r);}catch(err){toast(err.message,true);b.disabled=false;}return;}
  if(b.dataset.product)return productModal(Number(b.dataset.product));if(b.dataset.stock)return stockModal(Number(b.dataset.stock));if(b.dataset.receipt)return showReceipt(Number(b.dataset.receipt));if(b.dataset.access)return accessModal(Number(b.dataset.access));
  if(b.dataset.add){if(addCart(Number(b.dataset.add))){search='';render();toast('Produto adicionado. Pode adicionar outros antes de finalizar.');}return;}if(b.dataset.remove){cart=cart.filter(i=>i.product_id!==Number(b.dataset.remove));render();return;}
  const action=b.dataset.action;
  if(action==='account-recovery'){showModal('Recuperar a sua palavra-passe',`<p>Não é possível mostrar a palavra-passe atual. Pode receber um código temporário no contacto registado e definir uma nova palavra-passe.</p><p>O envio por email ou SMS depende da configuração dos serviços. Se estiver indisponível, peça a reposição ao gerente ou proprietário autorizado.</p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Voltar à conta</button><button type="button" data-action="start-account-recovery">Continuar recuperação</button></div>`);return;}
  if(action==='start-account-recovery'){modal.close();await recoveryScreen();return;}

  if(action==='refresh-sale'){try{await refresh();toast('Preços, stock e regras fiscais atualizados. Confirme o total antes de finalizar.');}catch(err){toast(err.message,true);}return;}
  if(action==='new-tax-rule')return taxRuleModal();if(b.dataset.taxRule)return taxRuleModal(Number(b.dataset.taxRule));
  if(action==='continue-shopping'){search='';category='';render();$('#pos-search').focus();document.querySelector('.product-grid')?.scrollIntoView({block:'nearest',behavior:'smooth'});return;}
  if(action==='forgot')return recoveryScreen();if(action==='login')return auth(false);if(action==='retry')return boot();if(action==='transfer')return transferModal();
  if(action==='close')modal.close();if(action==='new-product')productModal();if(action==='new-user')userModal();if(action==='open-shift')shiftModal();if(action==='close-shift')shiftModal(true);if(action==='print')window.print();
  if(action==='logout'){try{await api('logout',{});state=null;cart=[];saleDraft={customer:'',discount:'0',paid:'',method:'dinheiro'};page='dashboard';auth(false);}catch(err){toast(err.message,true);}}
  if(action==='alerts'){page='products';stockOnly=true;search='';category='';render();}
  if(action==='toggle-low'){stockOnly=!stockOnly;render();}
  if(action==='clear-cart'){if(cart.length)showModal('Limpar a venda atual?',`<p>Os produtos desta venda serão removidos. Nenhuma venda será gravada.</p><div class="modal-actions"><button class="secondary" data-action="close">Voltar</button><button class="danger" data-action="confirm-clear">Limpar venda</button></div>`);}
  if(action==='confirm-clear'){cart=[];saleDraft={customer:'',discount:'0',paid:'',method:'dinheiro'};$('#sale-form')?.reset();modal.close();render();}
  if(action==='barcode'){showModal('Leitura de códigos de barras',`<p>Ligue um leitor USB ou Bluetooth configurado como teclado, com sufixo Enter. Depois, coloque o cursor no campo de pesquisa e leia o código.</p><p>O produto deve ter o código registado no catálogo. A leitura por câmara não está incluída nesta versão.</p><div class="modal-actions"><button data-action="scan-focus">Ativar campo de leitura</button></div>`);}
  if(action==='scan-focus'){modal.close();$('#pos-search').focus();}
  if(action==='clear-history'){$('#history-form').reset();clearTimeout(historyTimer);return loadHistory();}
  if(action==='export'){if(!historyResult)return;const cell=v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Recibo','Caixa','Data UTC','Cliente','Vendedor','Pagamento','Subtotal Kz','Desconto Kz','Total Kz','Entregue Kz','Troco Kz','Estado IVA','Base Kz','IVA Kz'],...historyResult.sales.map(s=>[s.id,s.shift_id,s.created,s.customer,s.seller,methodLabel[s.method],s.subtotal/100,s.discount/100,s.total/100,s.paid/100,s.change_due/100,s.fiscal_state,s.tax_base===null?'':s.tax_base/100,s.tax_total===null?'':s.tax_total/100])];const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='vendas-loja-clara.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
});
modal.addEventListener('close',()=>{if(!modal.open)modal.replaceChildren();});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
function dashboardHero(){const hour=Number(new Intl.DateTimeFormat('en',{hour:'numeric',hour12:false,timeZone:'Africa/Luanda'}).format(new Date()));const greeting=hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite';return `<section class="dashboard-hero"><div class="hero-copy"><div class="hero-kicker"><span></span> O SEU NEGÓCIO, EM MOVIMENTO</div><h1>${greeting}, <span>${esc(state.user.name.split(' ')[0])}.</span><br>Vamos fazer acontecer?</h1><p>Transforme os números de hoje nas conquistas de amanhã.<br>A sua loja, a sua equipa, tudo conectado.</p><button data-page="sales">Iniciar uma venda ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="hero-art-card"><div class="art-card-label">TT LEBILA <span>● AO VIVO</span></div><div class="art-total">${money(state.metrics.today)}</div><div class="art-caption">em vendas hoje</div><div class="art-spark">${chart().replaceAll('id="area"','id="hero-area"').replaceAll('url(#area)','url(#hero-area)')}</div><div class="art-card-footer">${icon('trend')} Cada movimento conta.</div></div><div class="art-badge">${icon('check')} Gestão com confiança</div></div></section>`;}
function removeUserModal(id){const u=state.users.find(x=>x.id===id);showModal('Remover '+esc(u.name)+'?',`<p>Esta pessoa deixará de poder entrar. Os seus recibos, caixas e atividades continuarão no histórico. É necessário fechar o caixa antes da remoção.</p><form id="remove-user-form"><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button class="danger">Confirmar remoção</button></div></form>`);$('#remove-user-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,()=>api('users/remove',{id}),'Utilizador removido. Histórico preservado.');};}
function transferModal(){const targets=state.users.filter(u=>u.id!==state.user.id&&u.active);if(!targets.length)return toast('Cadastre primeiro a pessoa que vai assumir a propriedade.',true);showModal('Transferir a propriedade',`<form id="transfer-form"><div class="notice">Apenas uma pessoa pode ser proprietária. Ao confirmar, passará a vendedor e as sessões dos dois utilizadores serão terminadas. Esta operação fica registada.</div>${select('Novo proprietário','id',targets.map(u=>[String(u.id),u.name+' · '+roleLabel[u.role]]))}${field('Confirme a sua palavra-passe','password','password','','required autocomplete="current-password"')}<div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>Confirmar transferência</button></div></form>`);$('#transfer-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button:not([type="button"])');b.disabled=true;try{const d=formData(f);await api('users/transfer-owner',{id:Number(d.id),password:d.password});modal.close();state=null;cart=[];auth(false);toast('Propriedade transferida. Inicie sessão novamente.');}catch(err){formError(f,err);}finally{b.disabled=false;}};}
let recoveryTimer;
function accessLayout(content){app.innerHTML=`<div class="recovery-page"><div class="brand"><div class="brand-mark"><span class="tt-symbol">TT</span></div><div class="brand-name">LEBILA<small>COMÉRCIO & GESTÃO</small></div></div><section class="recovery-card">${content}</section><p class="recovery-footer">TT LEBILA · A confiança faz parte do nosso negócio.</p></div>`;}
async function recoveryScreen(){clearInterval(recoveryTimer);accessLayout(`<div class="eyebrow">VAMOS RECUPERAR O SEU ACESSO</div><h1>Esqueceu a palavra-passe?</h1><p>Enviaremos um código de 6 algarismos para o email ou telefone já associado à sua conta. É válido durante 2 minutos.</p><form id="recover-form">${field('Email ou BI da conta','identifier','text','','required autocomplete="username"')}${select('Como quer receber o código?','channel',[['email','Email'],['sms','SMS no telefone registado']])}<div id="recovery-availability" class="notice">A verificar os canais disponíveis…</div><button type="submit">Enviar código ${icon('arrow')}</button><button type="button" class="forgot-button" data-action="login">Voltar ao login</button></form>`);let options;try{options=await api('recovery/options');}catch(e){$('#recovery-availability').textContent=e.message;return;}if(!$('#recover-form'))return;$('#recovery-availability').textContent=options.email||options.sms?'O destino é sempre o contacto registado. Não é possível indicar outro email ou telefone neste pedido.':'O envio de email e SMS ainda não foi ativado pelo proprietário. Peça-lhe a reposição da sua palavra-passe.';for(const o of $('#channel').options)o.disabled=!options[o.value];if(options.email)$('#channel').value='email';else if(options.sms)$('#channel').value='sms';$('#recover-form button[type="submit"]').disabled=!options.email&&!options.sms;$('#recover-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button[type="submit"]');b.disabled=true;try{const d=formData(f),r=await api('recovery/request',d);codeScreen(r,d);}catch(err){formError(f,err);}finally{b.disabled=false;}};}
function codeScreen(result,request){const deadline=Date.now()+result.expires_in*1000;accessLayout(`<div class="eyebrow">CONFIRME QUE É VOCÊ</div><h1>Introduza o seu código</h1><p>${esc(result.message)}</p><div class="code-countdown" id="countdown" role="timer">02:00</div><form id="code-form">${field('Código temporário','code','text','','required inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" data-code placeholder="000000"')}<button>Entrar com código</button><button type="button" class="forgot-button" data-action="forgot">Pedir outro código</button><button type="button" class="forgot-button" data-action="login">Voltar ao login</button></form>`);clearInterval(recoveryTimer);recoveryTimer=setInterval(()=>{if(!$('#countdown'))return clearInterval(recoveryTimer);const remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('#countdown').textContent=remaining?`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`:'Código expirado · peça outro';if(!remaining){$('#code-form button:not([type="button"])').disabled=true;clearInterval(recoveryTimer);}},1000);$('#code-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button:not([type="button"])');b.disabled=true;try{await api('recovery/verify',{challenge:result.challenge,code:formData(f).code});clearInterval(recoveryTimer);await refresh();}catch(err){formError(f,err);}finally{b.disabled=false;}};}
function resetScreen(){accessLayout(`<div class="eyebrow">ACESSO RECUPERADO</div><h1>Crie uma nova palavra-passe</h1><p>Olá, ${esc(state.user.name)}. A sua senha antiga não pode ser visualizada. Defina uma nova para continuar para a loja.</p><form id="recovered-password-form">${field('Nova palavra-passe','password','password','','required minlength="8" autocomplete="new-password" data-strong-password')}${field('Confirmar palavra-passe','confirmation','password','','required minlength="8" autocomplete="new-password"')}<div class="password-rules">8 ou mais caracteres · letras · números · carácter especial</div><button>Guardar e entrar na loja ${icon('arrow')}</button><button class="forgot-button" type="button" data-action="logout">Terminar sessão</button></form>`);$('#recovered-password-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=formData(f),b=f.querySelector('button:not([type="button"])');if(d.password!==d.confirmation)return formError(f,Error('As palavras-passe não coincidem.'));b.disabled=true;try{await api('password',{password:d.password});page='dashboard';await refresh();toast('Palavra-passe atualizada. Bem-vindo de volta!');}catch(err){formError(f,err);}finally{b.disabled=false;}};}
function installFilters(){if(['dashboard','account','sales','fiscal','history'].includes(page))return;const wrappers=[...document.querySelectorAll('.table-wrap')];wrappers.forEach((wrap,index)=>{
 if(page==='products'&&index===0)return;
 const rows=[...wrap.querySelectorAll('tbody tr')];if(!rows.length)return;
 const records=page==='history'?state.sales:page==='activity'?state.audit:page==='cash'?state.shifts:page==='products'?state.purchases:state.users;
 const column={history:3,activity:0,users:3,cash:2,products:1}[page];
 const unique=[...new Set(rows.map(r=>page==='cash'?(r.children[2].textContent.trim()==='Aberto'?'Aberto':'Fechado'):r.children[column]?.textContent.trim()))].filter(Boolean).sort();
 const dated=page!=='users',id='filter-'+page+'-'+index;
 const f=filters[id]||{q:'',kind:'',start:'',end:'',active:''};filters[id]=f;
 const bar=document.createElement('div');bar.className='filter-bar';bar.innerHTML=`<div class="filter-query"><label for="${id}-q">Pesquisar</label><input id="${id}-q" placeholder="Escreva para filtrar…" value="${esc(f.q)}"></div><div><label for="${id}-kind">${({history:'Pagamento',users:'Perfil',activity:'Atividade',cash:'Estado',products:'Produto'})[page]}</label><select id="${id}-kind"><option value="">Todos</option>${unique.map(v=>`<option ${v===f.kind?'selected':''}>${esc(v)}</option>`).join('')}</select></div>${page==='users'?`<div><label for="${id}-active">Estado</label><select id="${id}-active"><option value="">Todos</option><option value="1" ${f.active==='1'?'selected':''}>Ativos</option><option value="0" ${f.active==='0'?'selected':''}>Inativos</option></select></div>`:''}${dated?`<div><label for="${id}-start">De</label><input id="${id}-start" type="date" value="${f.start}"></div><div><label for="${id}-end">Até</label><input id="${id}-end" type="date" value="${f.end}"></div>`:''}<button class="ghost small" type="button" data-clear-filters>Limpar filtros</button><span class="filter-count" aria-live="polite"></span>`;
 wrap.before(bar);const no=document.createElement('tr');no.innerHTML=`<td colspan="${rows[0].children.length}" class="empty">Nenhum registo corresponde aos filtros.</td>`;wrap.querySelector('tbody').append(no);
 function apply(){let count=0;rows.forEach((row,i)=>{const record=records[i],value=page==='cash'?(record?.closed?'Fechado':'Aberto'):row.children[column]?.textContent.trim();const timestamp=record?.created||record?.opened;const day=timestamp?new Date(new Date(timestamp.replace(' ','T')+'Z').getTime()+3600000).toISOString().slice(0,10):'';const visible=row.textContent.toLocaleLowerCase('pt').includes(f.q.toLocaleLowerCase('pt'))&&(!f.kind||f.kind===value)&&(!f.active||String(record?.active)===f.active)&&(!f.start||day>=f.start)&&(!f.end||day<=f.end);row.hidden=!visible;if(visible)count++;});no.hidden=!!count;bar.querySelector('.filter-count').textContent=`${count} de ${rows.length} registos carregados`;}
 for(const key of ['q','kind',...(page==='users'?['active']:[]),...(dated?['start','end']:[])]){const input=document.getElementById(id+'-'+key);input.addEventListener('input',()=>{f[key]=input.value;apply();});}
 bar.querySelector('[data-clear-filters]').onclick=()=>{for(const key of ['q','kind','start','end','active']){f[key]='';const input=document.getElementById(id+'-'+key);if(input)input.value='';}apply();};apply();
 });}
document.addEventListener('input',e=>{const el=e.target;if(!(el instanceof HTMLInputElement))return;
 if(el.hasAttribute('data-number')){const before=el.value.slice(0,el.selectionStart).replace(/\s/g,'').length;el.value=numericDisplay(el.value,Number(el.dataset.decimals||0));let logical=0,pos=0;for(;pos<el.value.length&&logical<before;pos++)if(el.value[pos]!==' ')logical++;el.setSelectionRange(pos,pos);const value=num(el.value),min=Number(el.dataset.min??0);el.setCustomValidity(el.value&&(!Number.isFinite(value)||value<min)?`Introduza um valor igual ou superior a ${min}.`:'');}
 if(el.hasAttribute('data-quantity'))updateCartQuantity(el);
 if(page==='sales'&&['paid','discount'].includes(el.id))updateTotals();
 if(el.hasAttribute('data-bi')){el.value=el.value.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,14);el.setCustomValidity(el.value&&!/^\d{9}[A-Z]{2}\d{3}$/.test(el.value)?'O BI deve ter 9 algarismos, 2 letras e 3 algarismos. Exemplo: 009763932CA042.':'');}
 if(el.hasAttribute('data-descriptive')){const start=el.selectionStart,end=el.selectionEnd;el.value=descriptiveText(el.value);el.setSelectionRange(start,end);}
 if(el.hasAttribute('data-person-name')||el.hasAttribute('data-product-name')){const start=el.selectionStart,end=el.selectionEnd;el.value=titleName(el.value);el.setSelectionRange(start,end);el.setCustomValidity(nameError(el.value,el.hasAttribute('data-product-name')));}
 if(el.hasAttribute('data-phone')){el.value=el.value.replace(/[^+0-9 ()-]/g,'').replace(/(?!^)\+/g,'');}
 if(el.type==='email'){el.value=el.value.toLowerCase();el.setCustomValidity(el.value&&!gmailValid(el.value)?'Use letras minúsculas, números ou _ antes de @gmail.com. Não são permitidos espaços nem pontos no nome.':'');}
 if(el.hasAttribute('data-code'))el.value=el.value.replace(/\D/g,'').slice(0,6);
 if(el.hasAttribute('data-strong-password'))el.setCustomValidity(el.value&&!(el.value.length>=8&&/[A-Za-z]/.test(el.value)&&/\d/.test(el.value)&&/[^a-zA-Z0-9\s]/.test(el.value))?'Use pelo menos 8 caracteres, letras, números e um carácter especial.':'');
});

function taxLabel(rule){if(!rule)return 'Por definir';if(rule.kind==='isento')return 'Isento';if(rule.kind==='nao_sujeito')return 'Não sujeito';return `${qty(rule.rate_bps/100)}%`;}
function fiscalBanner(){const f=state.fiscal.settings;return `<div class="banner fiscal-banner"><div><strong>${f.enabled?'IVA configurado · confirme o total antes de receber':'IVA não apurado · enquadramento pendente'}</strong><p>${f.enabled?(f.price_mode==='included'?'Os preços já incluem IVA. O imposto é separado depois de distribuir o desconto.':'Os preços não incluem IVA. O imposto é acrescido depois de distribuir o desconto.'):'Não foi aplicada uma taxa automática. Estas vendas geram apenas comprovativos internos com IVA por apurar.'}</p></div>${can('fiscal')?'<button class="secondary small" data-page="fiscal">IVA e regras fiscais</button>':''}</div>`;}
function fiscalText(label,name,value,id=name,required=false){return `<div class="field">${inputLabel(label,id,required)}<textarea id="${id}" name="${name}" ${required?'required':''} rows="3" maxlength="2000">${esc(value||'')}</textarea></div>`;}
function fiscalPage(){const f=state.fiscal.settings,owner=state.user.role==='proprietario';return heading('REGRAS CLARAS. CONTAS TRANSPARENTES.','IVA e regras fiscais','Configure o enquadramento e a incidência por produto. Não é uma declaração fiscal.')+`<div class="notice fiscal-notice"><strong>${f.enabled?'Regras introduzidas e ativadas pelo proprietário':'Configuração fiscal pendente - nenhuma taxa é aplicada automaticamente'}</strong><p>O enquadramento da TT LEBILA e a legislação em vigor ainda precisam de confirmação. Alimentares não significa automaticamente isento ou sujeito a uma taxa reduzida. Registe o diploma, artigo e classificação confirmados com o contabilista.</p><p><a href="https://agt.minfin.gov.ao/" target="_blank" rel="noopener noreferrer">Consultar o portal oficial da AGT ↗</a> · O cálculo não torna este software fiscalmente certificado.</p></div><div class="stack"><section class="card shift-card"><h2>Enquadramento da empresa</h2><p>Gerente e vendedores usam as regras definidas; apenas o proprietário as altera.</p>${owner?`<form id="fiscal-settings-form"><div class="form-grid">${select('Regime de IVA','regime',[['pendente','Ainda por confirmar'],['geral','Geral'],['exclusao','Exclusão / não enquadrada'],['simplificado','Simplificado - requer apuramento específico']],f.regime)}${select('Estado do cálculo','enabled',[['false','Pendente - sem IVA apurado'],['true','Ativar as regras confirmadas']],String(!!f.enabled))}${select('O preço de venda registado no catálogo…','price_mode',[['included','Já inclui IVA'],['excluded','Não inclui IVA (acrescer na venda)']],f.price_mode)}${field('NIF da empresa','company_nif','text',f.company_nif,'maxlength="14"'+(f.enabled?' required':'' ))}<div class="full">${field('Morada do estabelecimento','company_address','text',f.company_address,'maxlength="500"'+(f.enabled?' required':''))}${fiscalText('Fundamento do enquadramento (diploma, artigo e confirmação do contabilista)','legal_basis',f.legal_basis,'settings_legal_basis',!!f.enabled)}</div></div><label class="checkbox-label"><input type="checkbox" name="confirmed" ${f.enabled?'required':''}><span>Confirmo o enquadramento e as regras com base na legislação aplicável. Percebo que mudar o modo de preço não altera os preços já registados.${f.enabled?' '+requiredMarker():''}</span></label><p class="help">Se não souber o regime, mantenha o cálculo pendente. O apuramento específico do regime simplificado e a dedução de IVA das compras não estão implementados.</p><button>Guardar enquadramento</button></form>`:`<p>Regime: <strong>${esc(f.regime)}</strong><br>Estado: <strong>${f.enabled?'Ativo':'Pendente'}</strong><br>Preços: <strong>${f.price_mode==='included'?'Com IVA incluído, quando ativo':'Sem IVA, quando ativo'}</strong><br>NIF: ${esc(f.company_nif||'Por definir')}<br>Fundamento: ${esc(f.legal_basis||'Por confirmar')}</p>`}</section><section class="card"><div class="card-head table-title"><div><h2>Taxas, isenções e não sujeição</h2><p>Sem taxas predefinidas ou presumidas por categoria.</p></div>${owner?'<button data-action="new-tax-rule">'+icon('plus')+'Nova regra</button>':''}</div>${state.fiscal.rules.length?`<div class="table-wrap"><table><thead><tr><th>REGRA</th><th>INCIDÊNCIA</th><th>VIGÊNCIA</th><th>FUNDAMENTO LEGAL</th><th>ESTADO</th><th></th></tr></thead><tbody>${state.fiscal.rules.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${taxLabel(r)}</td><td>${esc(r.start_date)} → ${esc(r.end_date||'sem fim definido')}</td><td class="legal-cell">${esc(r.legal_basis)}</td><td><span class="tag ${r.active?'':'gray'}">${r.active?'Ativa':'Inativa'}</span></td><td>${owner?`<button class="secondary small" data-tax-rule="${r.id}">Editar regra</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Ainda não há regras. O proprietário deve introduzir apenas as taxas e fundamentos legais confirmados.','receipt')}</section><section class="card shift-card"><h2>Classificar produtos do stock</h2><p>Atribua uma regra a um ou vários produtos, sem alterar quantidades nem custos. As vendas anteriores mantêm a sua classificação original.</p>${state.fiscal.rules.some(r=>r.active)&&state.products.length?`<form id="product-tax-form">${select('Regra a aplicar','tax_rule_id',state.fiscal.rules.filter(r=>r.active).map(r=>[String(r.id),r.name+' · '+taxLabel(r)]))}<div class="field"><label for="tax-product-search">Pesquisar produtos para classificar</label><input id="tax-product-search" placeholder="Nome, categoria ou código…"></div><fieldset class="product-tax-fieldset"><legend>Produtos a classificar ${requiredMarker()}</legend><p class="help">Selecione pelo menos um produto.</p><div class="product-tax-list">${state.products.map(p=>`<label class="checkbox-label tax-product-option" data-product-search="${esc((p.name+' '+p.category+' '+(p.barcode||'')).toLowerCase())}"><input type="checkbox" value="${p.id}"><span><strong>${esc(p.name)}</strong><small>${esc(p.category)} · ${taxLabel(state.fiscal.rules.find(r=>r.id===p.tax_rule_id))}</small></span></label>`).join('')}</div></fieldset><button>Aplicar aos produtos selecionados</button></form>`:empty('Cadastre produtos e pelo menos uma regra ativa para classificar o stock.','box')}</section><section class="card shift-card"><h2>Resumo de IVA nas vendas</h2><p>Valores registados nos comprovativos, por data da venda em Angola. Não substitui a declaração de IVA nem inclui imposto dedutível das compras.</p><form id="tax-report-form" class="report-form">${field('De','start','date',angolaDay().slice(0,8)+'01','required')}${field('Até','end','date',angolaDay(),'required')}<button>Consultar período</button></form><div id="tax-report-result"></div></section></div>`;}
function taxRuleModal(id){const r=state.fiscal.rules.find(r=>r.id===id)||{name:'',kind:'tributado',rate_bps:0,start_date:angolaDay(),end_date:'',legal_basis:'',active:1};showModal(id?'Editar regra de IVA':'Definir regra de IVA',`<form id="tax-rule-form">${field('Nome da regra','name','text',r.name,'required maxlength="150"')}${select('Tipo de incidência','kind',[['tributado','Tributado'],['isento','Isento'],['nao_sujeito','Não sujeito']],r.kind)}<div class="form-grid">${field('Taxa (%) - confirmada na legislação aplicável','rate','number',r.rate_bps/100,'required min="0" max="100" step="0.01"')}${select('Estado','active',[['true','Ativa'],['false','Inativa']],String(!!r.active))}${field('Vigente desde','start_date','date',r.start_date,'required')}${field('Vigente até (opcional)','end_date','date',r.end_date||'','')}</div>${fiscalText('Fundamento legal e âmbito dos produtos (obrigatório)','legal_basis',r.legal_basis,'legal_basis',true)}<p class="help">Isenção e não sujeição têm taxa 0%, mas são situações diferentes e exigem fundamento. As alterações só afetam novas vendas; os recibos anteriores mantêm as taxas originais.</p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>Guardar regra</button></div></form>`);const kind=$('#kind'),rate=$('#rate');function changeKind(){rate.readOnly=kind.value!=='tributado';if(rate.readOnly){rate.value='0';rate.setCustomValidity('');}}kind.onchange=changeKind;changeKind();$('#tax-rule-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=formData(f);await submit(f,()=>api('fiscal/rules',{...d,id,rate:Number(d.rate),active:d.active==='true'}),'Regra fiscal guardada.');};}
function renderTaxReport(r){$('#tax-report-result').innerHTML=`<div class="metrics report-metrics">${metric('Comprovativos no período',qty(r.sales_count),'Inclui vendas com IVA por apurar','receipt')}${metric('Base das vendas apuradas',money(r.tax_base),'Após descontos','chart')}${metric('IVA registado',money(r.tax_total),'Apenas vendas com regras aplicadas','cash')}${metric('IVA por apurar',qty(r.pending_count),'Comprovativos pendentes ou antigos','bell')}</div>${r.groups.length?`<div class="table-wrap"><table><thead><tr><th>REGRA / TAXA</th><th>BASE</th><th>IVA</th><th>TOTAL</th><th>FUNDAMENTO REGISTADO</th></tr></thead><tbody>${r.groups.map(g=>`<tr><td><strong>${esc(g.name)}</strong><span class="sub">${taxLabel(g)}</span></td><td>${money(g.tax_base)}</td><td>${money(g.tax_amount)}</td><td>${money(g.total)}</td><td class="legal-cell">${esc(g.legal_basis)}</td></tr>`).join('')}</tbody></table></div>`:empty('Não há IVA apurado neste período. As vendas pendentes não são consideradas isentas.','receipt')}`;}
function bindFiscal(){const settings=$('#fiscal-settings-form');if(settings){const sync=()=>{const active=$('#enabled').value==='true';for(const id of ['company_nif','company_address','settings_legal_basis'])document.getElementById(id).required=active;settings.querySelector('[name=confirmed]').required=active;markRequiredFields(settings);};$('#enabled').addEventListener('change',sync);sync();}if(settings)settings.onsubmit=async e=>{e.preventDefault();const d=formData(settings);await submit(settings,()=>api('fiscal/settings',{...d,enabled:d.enabled==='true',confirmed:d.confirmed==='on'}),'Enquadramento fiscal guardado.');};const products=$('#product-tax-form');if(products){$('#tax-product-search').oninput=e=>{const query=e.target.value.toLowerCase();for(const row of document.querySelectorAll('.tax-product-option'))row.hidden=!row.dataset.productSearch.includes(query);};products.onsubmit=async e=>{e.preventDefault();const ids=[...products.querySelectorAll('input[type="checkbox"]:checked')].map(input=>Number(input.value));if(!ids.length)return formError(products,Error('Selecione pelo menos um produto.'));await submit(products,()=>api('products/tax',{ids,tax_rule_id:Number($('#tax_rule_id').value)}),'Classificação fiscal atualizada.');};}$('#tax-report-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{renderTaxReport(await api('fiscal/report',formData(f)));}catch(err){formError(f,err);}finally{b.disabled=false;}};}

function markRequiredFields(root=document){
 for(const input of root.querySelectorAll('input,select,textarea')){
  if(['hidden','submit','button'].includes(input.type))continue;
  if(input.required&&input.getAttribute('aria-required')!=='true')input.setAttribute('aria-required','true');else if(!input.required&&input.hasAttribute('aria-required'))input.removeAttribute('aria-required');
  const labels=[...(input.labels||[])];
  for(const label of labels){
   const existing=label.querySelector('.required-marker');
   if(input.required&&!existing)label.insertAdjacentHTML('beforeend',' '+requiredMarker());
   else if(!input.required&&existing)existing.remove();
  }
 }
 for(const form of root.querySelectorAll('form')){
  const needed=form.querySelector('[required]')||form.querySelector('legend .required-marker');
  if(needed&&!form.querySelector('.required-note'))form.insertAdjacentHTML('afterbegin',`<p class="required-note">${requiredMarker()} Campos obrigatórios</p>`);
 }
}
let requiredUpdatePending=false;
new MutationObserver(()=>{if(requiredUpdatePending)return;requiredUpdatePending=true;queueMicrotask(()=>{requiredUpdatePending=false;markRequiredFields();});}).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['required']});

boot();
